// The Core 2 combat screen's plain C# view models (Runtime/Presentation/Core2/Combat), engine-free, over real Core2Fights.
// Run from the repository root: dotnet run --project UnityTests/Core2CombatView [-- <repo root>]
//
// 1. JS oracle (js-combat-view-oracle.json, generated by js-combat-view-oracle.mjs at the SPEC pin): five whole fights
//    from the reaction-fights family are driven through Core2CombatController exactly as the JS driver drove them, and
//    after every command the beats (fx.js groupBeats), the hit floaters (guardHitFloatParts, dmgClass), the enemy intent
//    reads (combatIntentPresentation over projectCombatIntent) and the reaction window (stack names, Back / Resolve, the
//    incoming line) must equal the JS screen's. Pure tables: hotkeys, size tiers, badge order, callout words, copy,
//    pacing, and the stage times of runActionTimeline for recorded dispatches at four paces.
// 2. Screen behaviour the oracle does not reach, on a real Core 2 run: the opening model, input gates while beats play
//    and while an offer is pending, keys, the Reaction switch, Auto answering an offer after one gap, flasks, the hit
//    badge against the hit the play then rolled, the log drawer, the pacing presets, the inspector and the fight-over
//    report (exactly once).
using System.Globalization;
using AshenSpire.Domain.Core2;
using AshenSpire.Presentation.Core2;
using Newtonsoft.Json.Linq;

var root = args.Length > 0 && !args[0].StartsWith("--") ? args[0] : ".";
var checks = 0;
var failures = 0;
void Check(bool condition, string label)
{
    if (condition) { checks++; Console.WriteLine("PASS: " + label); }
    else { failures++; Console.Error.WriteLine("FAIL: " + label); }
}
void Equal<T>(T actual, T expected, string label) => Check(Equals(actual, expected), label + (Equals(actual, expected) ? "" : " (actual '" + actual + "', expected '" + expected + "')"));
string Full(string relative) => Path.Combine(root, relative.Replace('/', Path.DirectorySeparatorChar));
string Read(string relative) => File.ReadAllText(Full(relative));

try
{
    var content = Core2Content.LoadFolder(Full("GameContent/Unity/Core2"));
    var data = new Core2RunData(content);
    var oracle = JObject.Parse(Read("UnityTests/Core2CombatView/js-combat-view-oracle.json"));
    var reactionFights = JObject.Parse(Read("UnityTests/Core2Content/Oracles/reaction-fights.json"));
    var cardArt = (JObject)JObject.Parse(Read("Unity/Assets/AshenSpire/Resources/Core2Ui/card-art.json"))["cards"];
    var art = cardArt.Properties().ToDictionary(p => p.Name, p => (string)p.Value["resource"]);
    Equal((string)oracle["js"]?["commit"], content.Manifest.JsCommit, "oracle: generated at the export's JS commit");
    Equal((string)oracle["profileHash"], content.Manifest.ProfileHash, "oracle: generated from the export's profile hash");

    // ==== 1a. the oracle fights ======================================================================================
    var paceDefault = new JObject();
    foreach (var fightCase in ((JArray)oracle["fights"]).OfType<JObject>())
    {
        var input = (JObject)fightCase["input"];
        var label = (string)input["classId"] + "/" + (int)input["seed"] + "/" + string.Join(",", input["enemyIds"]!.Select(t => (string)t)) + "/" + (string)input["policy"];
        var start = reactionFights["cases"]!.OfType<JObject>().First(c => (string)c["input"]!["classId"] == (string)input["classId"] && (int)c["input"]!["seed"] == (int)input["seed"]
            && c["input"]!["enemyIds"]!.ToString() == input["enemyIds"]!.ToString() && (string)c["input"]!["policy"] == (string)input["policy"])["input"]!["start"];
        var fight = Core2Fight.Create(content, Core2FightSetup.FromJson((JObject)start!), input["enemyIds"]!.Select(t => (string)t!).ToList(), (uint)(int)input["seed"]);
        var reported = 0;
        var controller = new Core2CombatController(null, () => reported++, new Core2CombatSettings(), art, fight);
        var steps = ((JArray)fightCase["steps"]!).OfType<JObject>().ToList();
        var mismatches = new List<string>();
        var now = 0.0;
        List<Core2CombatBeat> beats = null;
        bool Command(Func<bool> command)
        {
            var ok = command();
            beats = controller.Timeline?.Beats ?? new List<Core2CombatBeat>();
            now += 100000; controller.Tick(now);
            return ok;
        }
        void Compare(JObject expected, int index)
        {
            var where = label + " step " + index + " (" + (string)expected["command"] + ")";
            // beats
            var jsBeats = ((JArray)expected["beats"]!).OfType<JObject>().ToList();
            var csBeats = index == 0 ? new List<Core2CombatBeat>() : beats;
            if (jsBeats.Count != csBeats.Count) mismatches.Add(where + ": " + csBeats.Count + " beats, JS " + jsBeats.Count);
            else for (var b = 0; b < jsBeats.Count; b++)
            {
                var j = jsBeats[b]; var c = csBeats[b];
                var cs = (c.ActorId ?? "-") + "/" + (c.Kind ?? "-") + "/" + (c.Banner ?? "-") + "/" + c.Prepared + "/" + c.Telegraph + "/" + c.Lead + "/" + string.Join(",", c.Events.Select(e => e.Type));
                var js = ((string)j["actorId"] ?? "-") + "/" + ((string)j["kind"] ?? "-") + "/" + ((string)j["banner"] ?? "-") + "/" + (bool)j["prepared"]! + "/" + (bool)j["telegraph"]! + "/" + (int)j["lead"]! + "/" + string.Join(",", j["types"]!.Select(t => (string)t));
                if (cs != js) mismatches.Add(where + " beat " + b + ": " + cs + " | JS " + js);
            }
            // floaters for every hit
            var jsFloats = ((JArray)expected["floats"]!).OfType<JObject>().ToList();
            var hits = csBeats.SelectMany(b => b.Events).Where(e => e.Type == "damageDealt").ToList();
            if (hits.Count != jsFloats.Count) mismatches.Add(where + ": " + hits.Count + " hits, JS " + jsFloats.Count);
            else for (var h = 0; h < hits.Count; h++)
            {
                var floats = Core2CombatBeats.Numbers(new[] { hits[h] }, content, id => fight.Find(id)?.MaxHp ?? 0).Floaters;
                var j = jsFloats[h];
                string Text(string cls) => floats.FirstOrDefault(f => f.Class.StartsWith(cls, StringComparison.Ordinal))?.Text;
                var cs = Text("poise") + "|" + Text("blk") + "|" + Text("dmg") + "|" + floats.FirstOrDefault(f => f.Class.StartsWith("dmg", StringComparison.Ordinal))?.Class;
                var js = (string)j["poise"] + "|" + (string)j["guard"] + "|" + (string)j["damage"] + "|" + (string)j["damageClass"];
                if (cs != js) mismatches.Add(where + " hit " + h + ": " + cs + " | JS " + js);
            }
            // intents on the player's turn
            if (expected["intents"] is JArray jsIntents)
            {
                foreach (var j in jsIntents.OfType<JObject>())
                {
                    var enemy = fight.Find((string)j["enemyId"]);
                    var badge = Core2CombatViewModel.Intent(fight, enemy);
                    var cs = badge.Visibility + "|" + badge.Title + "|" + badge.Stance + "|" + badge.DamageClass + "|" + badge.Tone + "|" + string.Join(";", badge.Parts.Select(p => p.Icon + ":" + p.Value + ":" + p.Summary));
                    var js = (string)j["visibility"] + "|" + (string)j["title"] + "|" + (string)j["stance"] + "|" + (string)j["damageClass"] + "|" + (string)j["tone"] + "|"
                        + string.Join(";", j["parts"]!.Select(p => (string)p["icon"] + ":" + (string)p["value"] + ":" + (string)p["summary"]));
                    if (cs != js) mismatches.Add(where + " intent " + enemy.Id + ": " + cs + " | JS " + js);
                }
            }
            // the reaction window
            var jsOffer = expected["offer"] as JObject;
            var csOffer = controller.Model().Reaction;
            if ((jsOffer == null) != (csOffer == null)) mismatches.Add(where + ": offer " + (csOffer != null) + ", JS " + (jsOffer != null));
            else if (jsOffer != null)
            {
                var cs = csOffer.OfferId + "|" + csOffer.SourceId + "|" + string.Join(";", csOffer.Stack) + "|" + csOffer.DeclineLabel + "|" + csOffer.Incoming + "|" + string.Join(",", csOffer.Options.Select(o => o.Id));
                var js = (string)jsOffer["offerId"] + "|" + (string)jsOffer["sourceId"] + "|" + string.Join(";", jsOffer["stack"]!.Select(t => (string)t)) + "|" + (string)jsOffer["decline"] + "|" + (string)jsOffer["incoming"] + "|"
                    + string.Join(",", jsOffer["options"]!.Select(o => (string)o["id"]));
                if (cs != js) mismatches.Add(where + " offer: " + cs + " | JS " + js);
            }
            if ((string)expected["result"] != fight.Result) mismatches.Add(where + ": result " + fight.Result + ", JS " + (string)expected["result"]);
        }
        Compare(steps[0], 0);
        for (var index = 1; index < steps.Count; index++)
        {
            var command = (string)steps[index]["command"]!;
            var parts = command.Split(' ');
            bool ok;
            if (parts[0] == "endTurn") ok = Command(() => controller.EndTurn());
            else if (parts[0] == "answer") ok = Command(() => controller.AnswerReaction(parts[1] == "back" ? null : parts[1], manual: false));
            else
            {
                var instance = fight.Hand.FirstOrDefault(c => c.CardId == parts[1] && fight.CheckPlay(c.InstanceId, parts.Length > 2 ? parts[2] : null) == null)
                    ?? fight.Hand.FirstOrDefault(c => c.CardId == parts[1]);
                ok = instance != null && Command(() => controller.PlayCard(instance.InstanceId, parts.Length > 2 ? parts[2] : null));
            }
            if (!ok) { mismatches.Add(label + " step " + index + " (" + command + ") was refused: " + controller.LastRefusal); break; }
            Compare((JObject)steps[index], index);
        }
        now += 100000; controller.Tick(now);
        foreach (var m in mismatches.Take(12)) Console.Error.WriteLine("  " + m);
        Check(mismatches.Count == 0, "oracle fight " + label + ": " + (steps.Count - 1) + " commands through the controller; beats, hit floaters, intents and reaction windows equal the JS screen's" + (mismatches.Count > 0 ? " (" + mismatches.Count + " differences)" : ""));
        Equal(reported, fight.Result != null ? 1 : 0, "oracle fight " + label + ": the fight over is reported once (after its last beat)");
    }

    // ==== 1b. pure tables ============================================================================================
    var hotkeyMisses = 0;
    foreach (var row in ((JArray)oracle["hotkeys"]!).OfType<JObject>())
    {
        var got = Core2CardHotkey.For((string)row["key"], (bool)row["targeting"]!, (int)row["handSize"]!, (int)row["livingEnemies"]!);
        var expected = row["expected"] as JObject;
        var same = expected == null ? got == null : got != null && got.Kind == (string)expected["kind"] && (expected["index"] == null || got.Index == (int)expected["index"]!);
        if (!same) hotkeyMisses++;
    }
    Check(hotkeyMisses == 0, "cardHotkeyAction: " + ((JArray)oracle["hotkeys"]!).Count + " key/targeting/hand cases equal JS (1–9 select or target, Q is the 10th)");
    var tierMisses = ((JArray)oracle["damageClasses"]!).OfType<JObject>().Count(row => Core2CombatBeats.DamageClass((int)row["amount"]!, (int)row["maxHp"]!) != (string)row["expected"]);
    Check(tierMisses == 0, "dmgClass: floater size tiers equal JS (pct35, crit, pct20, heavy, small)");
    var healthMisses = 0;
    foreach (var row in ((JArray)oracle["health"]!).OfType<JObject>())
    {
        var i = (JObject)row["input"]!;
        var shown = new Core2DisplayFighter { Block = (int)i["defense"]!, Ward = (int)i["ward"]!, Poise = (int)i["poise"]!, PoiseMax = (int)i["poiseMax"]! };
        if ((int)i["evasion"]! > 0) shown.Statuses["evade"] = (int)i["evasion"]!;
        if ((int)i["precision"]! > 0) shown.Statuses["precision"] = (int)i["precision"]!;
        var got = string.Join(",", Core2CombatViewModel.Badges(shown).Select(b => b.Kind + ":" + b.Value));
        if (got != string.Join(",", row["expected"]!.Select(t => (string)t))) { healthMisses++; Console.Error.WriteLine("  badges " + got + " | JS " + string.Join(",", row["expected"]!.Select(t => (string)t))); }
    }
    Check(healthMisses == 0, "combatHealthModel: the defence badges come in the JS build's order (Block, Evade, Precision, Poise, Ward)");
    foreach (var p in ((JObject)oracle["callouts"]!).Properties())
    {
        var id = "combat.callout." + p.Name;
        Equal(Core2CombatText.T(id), (string)p.Value["text"], "callout word " + p.Name);
    }
    foreach (var p in ((JObject)oracle["strings"]!).Properties())
        Equal(Core2CombatText.T(p.Name), (string)p.Value, "copy " + p.Name);

    // ==== 1c. pacing and the timeline ================================================================================
    var pacing = new Core2CombatPacing(content);
    var settingsFor = new Dictionary<string, JObject>
    {
        ["default"] = new JObject(), ["mobileFast"] = pacing.Changes("combatPacingPreset", "mobile-fast"),
        ["auto"] = new JObject { ["autoCombat"] = true },
    };
    settingsFor["autoMobileFast"] = (JObject)settingsFor["mobileFast"].DeepClone();
    settingsFor["autoMobileFast"]["autoCombat"] = true;
    foreach (var p in ((JObject)oracle["paces"]!).Properties())
    {
        var pace = pacing.Pace("normal", settingsFor[p.Name], false);
        var timing = Core2BeatTiming.From(pace);
        var close = Math.Abs(timing.GapMs - (double)p.Value["gapMs"]!) < 1e-6 && Math.Abs(timing.StepMs - (double)p.Value["stepMs"]!) < 1e-6
            && Math.Abs(timing.BannerMs - (double)p.Value["bannerMs"]!) < 1e-6 && Math.Abs(timing.LungeMs - (double)p.Value["lungeMs"]!) < 1e-6;
        Check(close, "pace " + p.Name + ": gap " + timing.GapMs.ToString("0.###", CultureInfo.InvariantCulture) + " ms, step, banner and lunge equal JS actionPacing");
    }
    {
        // Replay fight 0 to the recorded dispatches and plan each at the four paces.
        var f0 = ((JArray)oracle["fights"]!)[0] as JObject;
        var input = (JObject)f0!["input"]!;
        var start = reactionFights["cases"]!.OfType<JObject>().First(c => (string)c["input"]!["classId"] == (string)input["classId"] && (int)c["input"]!["seed"] == (int)input["seed"]
            && c["input"]!["enemyIds"]!.ToString() == input["enemyIds"]!.ToString() && (string)c["input"]!["policy"] == (string)input["policy"])["input"]!["start"];
        var fight = Core2Fight.Create(content, Core2FightSetup.FromJson((JObject)start!), input["enemyIds"]!.Select(t => (string)t!).ToList(), (uint)(int)input["seed"]);
        var dispatches = new List<List<Core2FightEvent>>();
        foreach (var step in ((JArray)f0["steps"]!).Skip(1).OfType<JObject>())
        {
            var parts = ((string)step["command"]!).Split(' ');
            var mark = fight.Events.Count;
            if (parts[0] == "endTurn") fight.EndTurn();
            else if (parts[0] == "answer") fight.ChooseReaction(fight.PendingReaction.Id, parts[1] == "back" ? null : parts[1]);
            else fight.PlayCard((fight.Hand.FirstOrDefault(c => c.CardId == parts[1] && fight.CheckPlay(c.InstanceId, parts.Length > 2 ? parts[2] : null) == null) ?? fight.Hand.First(c => c.CardId == parts[1])).InstanceId, parts.Length > 2 ? parts[2] : null);
            dispatches.Add(fight.Events.Skip(mark).ToList());
            if (dispatches.Count > 12) break;
        }
        foreach (var tl in ((JArray)oracle["timelines"]!).OfType<JObject>())
        {
            var index = (int)tl["dispatch"]!;
            foreach (var p in ((JObject)tl["timelines"]!).Properties())
            {
                var timing = Core2BeatTiming.From(pacing.Pace("normal", settingsFor[p.Name], false));
                var plan = Core2CombatBeats.Plan(dispatches[index], content, timing, id => fight.Find(id)?.MaxHp ?? 0);
                var cs = string.Join(" ", plan.Steps.Select(s => s.Stage + "@" + Math.Round(s.AtMs, 3).ToString(CultureInfo.InvariantCulture))) + " end@" + Math.Round(plan.DurationMs, 3).ToString(CultureInfo.InvariantCulture);
                var js = string.Join(" ", p.Value["stages"]!.Select(s => (string)s["stage"] + "@" + ((double)s["at"]!).ToString(CultureInfo.InvariantCulture))) + " end@" + ((double)p.Value["endsAt"]!).ToString(CultureInfo.InvariantCulture);
                if (cs != js) Console.Error.WriteLine("  timeline " + index + " " + p.Name + ":\n    C# " + cs + "\n    JS " + js);
                Check(cs == js, "runActionTimeline: dispatch " + index + " at the " + p.Name + " pace — every stage at the JS time (" + plan.Steps.Count + " stages, " + Math.Round(plan.DurationMs) + " ms)");
            }
        }
    }

    // ==== 2. behaviour on a real Core 2 run ==========================================================================
    Core2RunSession FightSession(string classId, uint seed)
    {
        var s = Core2RunSession.Start(data, classId, seed, ignoreUnlocks: true);
        s.Travel(s.TravelOptions().First(id => s.Run.MapGraph.Node(id).Type is "monster" or "fight"));
        return s;
    }
    {
        var session = FightSession("reaver", 12345);
        var over = 0;
        var c = new Core2CombatController(session, () => over++, new Core2CombatSettings(), art);
        var m = c.Model();
        Equal(m.TurnRibbon, "Player Turn", "opening: the turn ribbon reads Player Turn");
        Equal(string.Join(",", m.Hand.Select(h => h.Key)), "1,2,3,4,5", "opening: the hand's slot keys read 1–5 (JS cardHotkeyAction)");
        Check(m.Hand.All(h => h.Playable), "opening: every card the engine would accept is playable");
        var strike = m.Hand.First(h => h.CardId == "core.strike");
        var defend = m.Hand.First(h => h.CardId == "core.defend");
        Equal(string.Join(" / ", strike.FaceLines), "12 damage", "card face: Reaver's Strike reads 12 damage (the JS hand face at the pin)");
        Equal(string.Join(" / ", defend.FaceLines), "Gain 14 Block", "card face: Defend reads Gain 14 Block (the JS hand face at the pin)");
        Equal(strike.TypeLabel + "|" + defend.TypeLabel, "ATTACK|DEFENSE", "card face: the type band reads ATTACK / DEFENSE");
        Equal(strike.Art, "Art/js1815/cards/art-cc839d43cd2202c2", "card face: Strike's painting is the JS O00 component art");
        Equal(m.Footer.EndTurnLabel + " · " + m.Footer.EndTurnKey + " · " + m.Footer.EndTurnHint, "End Turn · E · HOLD", "footer: End Turn · E · HOLD");
        Check(m.Footer.EndTurnNeedsHold && c.EndTurnNeedsHold, "footer: End Turn asks for the hold while a card is playable");
        Equal(m.Footer.Sp + "/" + m.Footer.MaxSp + " SP, " + m.Footer.Mp + "/" + m.Footer.MaxMp + " MP", "3/3 SP, 1/1 MP", "footer: the SP orb and MP pips show the turn's pools");
        Equal(m.Footer.DiscardLabel + " · " + m.Footer.ExhaustLabel + " · " + m.Footer.Draw + " " + m.Footer.DrawLabel, "Discard 0 · Exhaust 0 · 5 Draw", "footer: pile labels");
        Equal(m.Footer.ReactionState + "/" + m.Footer.AutoState, "enabled/disabled", "tools: Reaction enabled, Auto disabled by default");
        Equal(string.Join(",", m.Footer.Flasks.Select(f => f.Name + "×" + f.Charges)), "Crimson Flask×2,Azure Flask×1", "footer: the HP and MP flask charges");
        Equal(m.Top.HpText + " · " + m.Top.Cinders + " · " + string.Join(",", m.Top.Relics.Select(r => r.Name)), "71/71 · 20 · Forsaken Medallion,Ashen Grip", "top band: HP, Cinders, relics");
        Check(m.Backdrop.StartsWith("Art/js1815/combat/scenes/", StringComparison.Ordinal), "battlefield: the scene is one of the region paintings (" + m.Backdrop + ")");
        Equal(m.Enemies[0].Figure, "Art/js1815/combat/enemies/gildedKnight-idle", "battlefield: the enemy figure is its idle pose");
        Equal(m.Player.Figure, "Art/js1815/combat/player/reaver-ready", "battlefield: the player figure is the class's ready pose");
        Equal(string.Join(",", m.Enemies[0].Badges.Select(b => b.Kind)), "shield,precision,poise", "enemy HUD: Block, Precision, Poise badges in the JS order");
        Equal(m.Enemies[0].Intent.Title, "?", "enemy intent: an unread intent reads ?");

        // keys and the selection
        Check(c.Key("9"), "keys: 9 with a five-card hand is consumed and does nothing (JS kind none)");
        Check(c.Selected == null, "keys: … nothing is selected");
        var strikeSlot = (m.Hand.IndexOf(strike) + 1).ToString(CultureInfo.InvariantCulture);
        Check(c.Key(strikeSlot) && c.Selected == strike.InstanceId, "keys: the Strike's slot key arms it (a hostile card waits for its target)");
        var armed = c.Model();
        Equal(armed.Targeting, strike.InstanceId, "targeting: the armed Strike is the targeting card");
        Check(armed.Enemies[0].Targetable && armed.Enemies[0].HitBadge != null, "targeting: the enemy shows the hit-% badge (" + armed.Enemies[0].HitBadge + ")");
        var badge = armed.Enemies[0].HitBadge;
        var mark = c.Fight.Events.Count;
        Check(c.Key("1"), "keys: 1 while targeting plays the Strike at the first enemy");
        Check(c.Busy, "playback: the play's beats are playing");
        Check(!c.PlayCard(defend.InstanceId) && c.LastRefusal == "busy", "input gate: a second card is refused while beats play");
        var hit = c.Fight.Events.Skip(mark).FirstOrDefault(e => (e.Type == "attackHit" || e.Type == "attackMissed") && (string)e.Data["sourceId"] == "player");
        if (hit != null) Equal(badge, (int)hit.Data["hitChance"]! + "%", "hit badge: the % shown before the play is the hit chance the play then rolled against");
        c.Tick(1e6);
        Check(!c.Busy, "playback: the beats end by the clock");
        Equal(c.Display.Sp, c.Fight.Player.Stamina, "playback: the display returns to the fight's own numbers");

        // the reaction window holds every other input
        var guard = 0;
        while (c.Fight.PendingReaction == null && c.Fight.Result == null && guard++ < 10)
        {
            if (c.CanAct) c.EndTurn();
            c.Tick(c.NowMs + 1e6);
        }
        if (c.Fight.PendingReaction != null)
        {
            var rm = c.Model();
            Check(rm.Reaction != null && rm.InputLocked, "reaction: the window is open and every other input is locked");
            Equal(rm.Reaction.Eyebrow + " · " + rm.Reaction.Title, "Defensive reaction · Respond to the incoming action", "reaction: eyebrow and title");
            Check(rm.Reaction.Options.All(o => o.Costs.Count > 0 && o.Costs[0].EndsWith(" SP", StringComparison.Ordinal)), "reaction: each option shows its name and its SP price pill");
            Check(rm.Reaction.Threat != null && rm.Reaction.Threat.StartsWith("Gilded Knight", StringComparison.Ordinal), "reaction: the threat names its source (" + rm.Reaction.Threat + ")");
            Check(!c.EndTurn() && !c.Key("1") && !c.SetReactions(false), "reaction: End Turn, card keys and the switch are refused while the offer is pending");
            c.SelectReactionOption(rm.Reaction.Options[0].Id);
            Check(c.Model().Reaction.PlayEnabled, "reaction: choosing an option enables Play");
            Check(c.AnswerReaction(rm.Reaction.Options[0].Id), "reaction: Play answers the offer");
            c.Tick(c.NowMs + 1e6);
        }
        else Check(false, "reaction: the fight reached an offer to test");
    }
    {
        // The Reaction switch and Auto
        var session = FightSession("reaver", 12345);
        var c = new Core2CombatController(session, () => { }, new Core2CombatSettings(), art);
        Check(c.SetReactions(false) && !c.Fight.ReactionsEnabled, "Reaction switch: off between actions on the player turn");
        Equal(c.Model().Footer.ReactionState, "disabled", "Reaction switch: the pill reads disabled");
        c.SetReactions(true);
        c.SetAuto(true);
        Check(c.Settings.Auto && c.Model().Footer.AutoState == "enabled", "Auto pill: on, it reads enabled");
        var auto = c.Pace();
        Check(Math.Abs(auto.GapMs - 500 / 1.5) < 1e-6, "Auto: pacing runs at ×1.5 (the gap is 333 ms)");
        var strike = c.Fight.Hand.First(h => h.CardId == "core.strike");
        c.PlayCard(strike.InstanceId, c.Fight.Enemies[0].Id);
        c.Tick(c.NowMs + 1e6);
        Check(c.Fight.PendingReaction != null, "Auto: an offer is pending after the play (Gilded Knight's reaction)");
        var offer = c.Fight.PendingReaction?.Id;
        c.Tick(c.NowMs + 10);
        Check(c.Fight.PendingReaction?.Id == offer, "Auto: it waits one gap before answering");
        c.Tick(c.NowMs + 400);
        Check(c.Fight.PendingReaction?.Id != offer, "Auto: after the gap it answers the offer itself");
        Check(c.Fight.Phase == "player" || c.Fight.Result != null, "Auto: it never ends the turn");
    }
    {
        // Flasks
        var session = FightSession("starseer", 777);
        var c = new Core2CombatController(session, () => { }, new Core2CombatSettings(), art);
        var before = session.Run.FlaskCharges.ManaCurrent;
        Check(c.UseFlask("mana"), "flask: the Azure Flask is drunk in the fight");
        Equal(c.Timeline?.Beats.FirstOrDefault(b => b.Events.Any(e => e.Type == "flaskUsed"))?.ActionWord, "Azure Flask", "flask: its beat names the flask");
        c.Tick(c.NowMs + 1e6);
        Equal(session.Run.FlaskCharges.ManaCurrent, before - 1, "flask: one MP charge is spent");
    }
    {
        // Pacing presets and the log drawer
        var session = FightSession("rogue", 4242);
        var settings = new Core2CombatSettings();
        var c = new Core2CombatController(session, () => { }, settings, art);
        settings.Set(c.Pacing, "combatPacingPreset", "mobile-fast");
        Equal((int)settings.Values["combatStepPause"]! + "/" + (int)settings.Values["animationStepDuration"]!, "250/195", "pacing: mobile-fast writes 250 ms pause and 195 ms animation step");
        Equal(c.Pace().GapMs, 250.0, "pacing: the step pause is 250 ms");
        settings.Set(c.Pacing, "combatStepPause", 750);
        Equal(settings.Preset, "custom", "pacing: editing a value returns to Custom");
        var log = c.Log;
        Equal(log.Size, "Medium", "log: the drawer opens at Medium (JS COMBAT_LOG_DEFAULT_SIZE)");
        log.Key("ArrowUp"); Equal(log.Size, "Large", "log: ArrowUp grows it to Large");
        log.Key("ArrowDown"); log.Key("ArrowDown"); Equal(log.Size, "Small", "log: ArrowDown twice shrinks it to Small");
        log.Key("End"); Equal(log.Size, "Large", "log: End is Large");
        log.Key("Home"); Equal(log.Size, "Small", "log: Home is Small");
        var heights = log.Heights(234, 750, 640, 71);
        log.EndDrag(heights, heights["Medium"] + 5);
        Check(log.Size == "Medium" && log.Open, "log: a drag snaps to the nearest size and leaves the drawer open");
        Equal(log.DetailToggleLabel, "Full detail", "log door: the toggle reads Full detail");
        log.ToggleDetail();
        Equal(log.DetailToggleLabel, "Compact log", "log door: … then Compact log");
        var strike = c.Fight.Hand.FirstOrDefault(h => c.Fight.CardTargetsEnemy(h.InstanceId) && c.Fight.CheckPlay(h.InstanceId, c.Fight.Enemies[0].Id) == null);
        if (strike != null) { c.PlayCard(strike.InstanceId, c.Fight.Enemies[0].Id); c.Tick(c.NowMs + 1e6); }
        var rows = log.Rows(c.Fight, door: true);
        Equal(rows.FirstOrDefault()?.Kind + ":" + rows.FirstOrDefault()?.Text, "legend:Player | Enemy", "log: the legend names the two roles");
        Check(rows.Any(r => r.Kind == "heading" && r.Text == "Round 1"), "log: a Round 1 heading");
        Check(rows.Any(r => r.Kind == "detail" && r.Text.StartsWith("Hit 1:", StringComparison.Ordinal)), "log: full detail draws the damage receipt lines (Hit 1: … incoming → … HP damage)");
        var (player, enemy) = log.Palette;
        Equal(player + " " + enemy, "#7fc4ff #ff8d83", "log: the default palette");
        log.PlayerColorSetting = "#202020";
        Equal(log.Palette.Player, "#7fc4ff", "log: an unreadable name colour falls back to the readable default");
        // The inspector
        var inspect = Core2CombatViewModel.Inspect(c.Fight, c.Fight.Enemies[0]);
        Equal(string.Join(",", inspect.Sections.Select(s => s.Title)), "Summary,Current state,Previous actions,Enemy deck & played cards,Move set,Known traits", "inspector: the JS sections in order");
        Check(inspect.Sections[0].Rows.Any(r => r.Label == "Intent"), "inspector: the summary names the intent");
    }
    {
        // The fight over: reported once, after the last beat
        var session = FightSession("reaver", 99);
        var over = 0;
        var c = new Core2CombatController(session, () => over++, new Core2CombatSettings(), art);
        for (var guard = 0; guard < 400 && c.Fight.Result == null; guard++)
        {
            if (c.Fight.PendingReaction != null) { c.AnswerReaction(null, manual: false); }
            else if (c.CanAct)
            {
                var card = c.Fight.Hand.FirstOrDefault(h => c.Fight.CheckPlay(h.InstanceId, c.Fight.CardTargetsEnemy(h.InstanceId) ? c.Fight.Enemies.First(e => e.Alive).Id : null) == null);
                if (card != null) c.PlayCard(card.InstanceId, c.Fight.CardTargetsEnemy(card.InstanceId) ? c.Fight.Enemies.First(e => e.Alive).Id : null);
                else c.EndTurn();
            }
            c.Tick(c.NowMs + 1e6);
        }
        Check(c.Fight.Result != null, "fight over: the fight ended (" + c.Fight.Result + ")");
        Equal(over, 0, "fight over: not reported before the end delay has passed");
        c.Tick(c.NowMs + 1000);
        Equal(over, 1, "fight over: onFightOver ran once");
        c.Tick(c.NowMs + 1e6);
        Equal(over, 1, "fight over: … and only once");
        Check(!c.CanAct && !c.EndTurn(), "fight over: no command is accepted");
    }
}
catch (Exception error)
{
    failures++;
    Console.Error.WriteLine("FAIL: " + error);
}

if (failures > 0) { Console.Error.WriteLine("Core2CombatView: " + failures + " failed, " + checks + " passed"); return 1; }
Console.WriteLine("Core2CombatView: " + checks + " checks passed");
return 0;
